import { Registry } from "./core.js";
/**
 * The registry of palette commands, each with an optional keybind and slash command.
 *
 * @example
 * ```ts
 * ctx.add(Command, {
 *   id: "toggle",
 *   bind: "mod+shift+e",
 *   get title() {
 *     return ctx.t("command.toggle")
 *   },
 *   run: () => toggle(),
 * })
 * ```
 */
export const Command = Registry.define("command");
/**
 * The registry of host menu items.
 *
 * @example
 * ```ts
 * ctx.add(MenuItem, { menu: "session.panel", id: "open", title: ctx.t("open"), icon: "folder", run: () => open() })
 * ```
 */
export const MenuItem = Registry.define("menu-item");
/**
 * The registry of panels: tabs in the session's side region.
 *
 * @example
 * ```ts
 * ctx.add(Panel, {
 *   id: "main",
 *   region: "side",
 *   list: (input) => (input.open.includes("main") ? [tab] : []),
 *   render: (props) => <View session={props.session} />,
 * })
 * ```
 */
export const Panel = Registry.define("panel");
/**
 * The registry of settings pages, sections on host pages, and rows in host sections.
 *
 * @example
 * ```ts
 * ctx.add(SettingsPage, { id: "updates", page: "general", title: ctx.t("title"), render: () => <Section /> })
 * ```
 */
export const SettingsPage = Registry.define("settings-page");
/**
 * The registry of server sources the app lists.
 *
 * @example
 * ```ts
 * ctx.add(Server, () => ({ ready: loaded(), entries: hosts().map(toEntry) }))
 * ```
 */
export const Server = Registry.define("server");
/**
 * The registry of handlers that open local links, such as file paths in messages.
 *
 * @example
 * ```ts
 * ctx.add(LinkHandler, { match: (link) => link.href.endsWith(".md"), open: (link) => preview(link) })
 * ```
 */
export const LinkHandler = Registry.define("link-handler");
/**
 * The registry of titlebar pills.
 *
 * @example
 * ```ts
 * ctx.add(TitlebarItem, () => (ready() ? { id: "update", label: ctx.t("restart"), run: install } : undefined))
 * ```
 */
export const TitlebarItem = Registry.define("titlebar-item");
/**
 * The registry of pills above the session composer.
 *
 * @example
 * ```ts
 * ctx.add(ComposerPill, {
 *   id: "pulls",
 *   show: (input) => {
 *     const pulls = openPulls(input.session.directory)
 *     return pulls.length > 0 ? { icon: "github", label: ctx.plural("pulls", pulls.length) } : undefined
 *   },
 * })
 * ```
 */
export const ComposerPill = Registry.define("composer-pill");
/**
 * The registry of renderers for fenced code blocks, by language.
 *
 * @example
 * ```tsx
 * ctx.add(CodeBlock, {
 *   languages: ["csv"],
 *   render: (props) => {
 *     const rows = parseCsv(props.code)
 *
 *     return rows ? <CsvTable rows={rows} /> : undefined
 *   },
 * })
 * ```
 */
export const CodeBlock = Registry.define("code-block");
/**
 * The registry of buttons beside a fenced code block's Copy button, by language.
 *
 * @example
 * ```ts
 * ctx.add(CodeBlockAction, {
 *   id: "run",
 *   languages: ["sh", "bash", "shell"],
 *   icon: "terminal",
 *   get title() {
 *     return ctx.t("run")
 *   },
 *   run: (input) => runInTerminal(input.code, input.session),
 * })
 * ```
 */
export const CodeBlockAction = Registry.define("code-block-action");
/**
 * The registry of content for the host's slots (`SlotMap`).
 *
 * @example
 * ```ts
 * ctx.add(Slot, { at: "session.header", render: (input) => <Usage session={input.session} /> })
 * ```
 */
export const Slot = Registry.define("slot");
/**
 * The registry of CSS the host adds to the document while each item is contributed. Import the file with `?inline`.
 *
 * @example
 * ```ts
 * import css from "./dialog.css?inline"
 * ctx.add(Style, css)
 * ```
 */
export const Style = Registry.define("style");
/**
 * The registry of color themes the user can pick in Settings › Appearance, in the format of the app's own theme files.
 *
 * @example
 * ```ts
 * import theme from "./midnight.json"
 * ctx.add(Theme, theme)
 * ```
 */
export const Theme = Registry.define("theme");
